schema.code:
{
  "$schema": "http://json-schema.org/draft-07/schema#",
  "$id": "https://faion.net/schemas/llm-friendly-architecture.json",
  "title": "LLM-friendly architecture audit record",
  "type": "object",
  "required": ["repo", "owner", "inputs", "audit", "decision", "evidence", "review"],
  "additionalProperties": false,
  "definitions": {
    "path": {"type": "string", "minLength": 3, "pattern": "^[^\\s]+$"},
    "date": {"type": "string", "pattern": "^[0-9]{4}-[0-9]{2}-[0-9]{2}$"}
  },
  "properties": {
    "__faion_header__": {"type": "object"},
    "repo": {
      "type": "object",
      "required": ["url", "commit_sha", "source_root"],
      "additionalProperties": false,
      "properties": {
        "url": {"type": "string", "pattern": "^(https://|git@)"},
        "commit_sha": {"type": "string", "pattern": "^[0-9a-f]{7,40}$"},
        "source_root": {"$ref": "#/definitions/path"}
      }
    },
    "owner": {"type": "string", "pattern": "^[a-z-]+:[a-z0-9._-]+$"},
    "inputs": {
      "type": "array",
      "minItems": 1,
      "contains": {"properties": {"name": {"const": "line_limit"}}},
      "items": {
        "type": "object",
        "required": ["name", "value"],
        "additionalProperties": false,
        "properties": {
          "name": {"type": "string", "enum": ["line_limit", "namespace_import_allowlist"]},
          "value": {}
        },
        "allOf": [
          {"if": {"properties": {"name": {"const": "line_limit"}}},
           "then": {"properties": {"value": {"type": "integer", "minimum": 100, "maximum": 300, "default": 250}}}},
          {"if": {"properties": {"name": {"const": "namespace_import_allowlist"}}},
           "then": {"properties": {"value": {"type": "array", "items": {"type": "string", "minLength": 1}}}}}
        ]
      }
    },
    "audit": {
      "type": "object",
      "required": ["command", "file_size", "directory_depth", "barrels", "wildcard_imports", "naming", "inline_data", "claude_md", "ci_wired"],
      "additionalProperties": false,
      "properties": {
        "command": {"type": "string", "minLength": 8, "pattern": "audit"},
        "file_size": {
          "type": "object",
          "required": ["histogram", "oversized"],
          "additionalProperties": false,
          "properties": {
            "histogram": {
              "type": "array",
              "minItems": 2,
              "items": {
                "type": "object",
                "required": ["bucket", "files"],
                "additionalProperties": false,
                "properties": {
                  "bucket": {"type": "string", "pattern": "^[0-9]+(-[0-9]+|\\+)$"},
                  "files": {"type": "integer", "minimum": 0}
                }
              }
            },
            "oversized": {
              "type": "array",
              "items": {
                "type": "object",
                "required": ["path", "lines", "proposed_split"],
                "additionalProperties": false,
                "properties": {
                  "path": {"$ref": "#/definitions/path"},
                  "lines": {"type": "integer", "minimum": 101},
                  "proposed_split": {"type": "string", "minLength": 12, "pattern": "/"}
                }
              }
            }
          }
        },
        "directory_depth": {
          "type": "object",
          "required": ["limit", "feature_limit", "violations"],
          "additionalProperties": false,
          "properties": {
            "limit": {"type": "integer", "const": 3},
            "feature_limit": {"type": "integer", "const": 2},
            "violations": {
              "type": "array",
              "items": {
                "type": "object",
                "required": ["path", "depth"],
                "additionalProperties": false,
                "properties": {
                  "path": {"$ref": "#/definitions/path"},
                  "depth": {"type": "integer", "minimum": 4}
                }
              }
            }
          }
        },
        "barrels": {"type": "array", "items": {"$ref": "#/definitions/path"}},
        "wildcard_imports": {
          "type": "object",
          "required": ["lint", "hits"],
          "additionalProperties": false,
          "properties": {
            "lint": {"type": "string", "enum": ["ruff F403/F405", "eslint import/no-namespace", "eslint no-restricted-syntax", "biome noNamespaceImport"]},
            "hits": {
              "type": "array",
              "items": {
                "type": "object",
                "required": ["path", "line"],
                "additionalProperties": false,
                "properties": {"path": {"$ref": "#/definitions/path"}, "line": {"type": "integer", "minimum": 1}}
              }
            }
          }
        },
        "naming": {
          "type": "object",
          "required": ["rubric", "score", "offenders"],
          "additionalProperties": false,
          "properties": {
            "rubric": {"type": "array", "minItems": 4, "items": {"type": "string", "minLength": 8}},
            "score": {"type": "integer", "minimum": 0, "maximum": 100},
            "offenders": {
              "type": "array",
              "items": {
                "type": "object",
                "required": ["path", "reason", "proposed_name"],
                "additionalProperties": false,
                "properties": {
                  "path": {"$ref": "#/definitions/path"},
                  "reason": {"type": "string", "minLength": 8},
                  "proposed_name": {"$ref": "#/definitions/path"}
                }
              }
            }
          },
          "if": {"properties": {"score": {"maximum": 99}}},
          "then": {"properties": {"offenders": {"minItems": 1}}}
        },
        "inline_data": {
          "type": "array",
          "items": {
            "type": "object",
            "required": ["path", "lines"],
            "additionalProperties": false,
            "properties": {"path": {"$ref": "#/definitions/path"}, "lines": {"type": "integer", "minimum": 1}}
          }
        },
        "claude_md": {
          "type": "object",
          "required": ["present", "line_limit"],
          "additionalProperties": false,
          "properties": {
            "present": {"type": "boolean", "const": true},
            "line_limit": {"type": "integer", "minimum": 100, "maximum": 300}
          }
        },
        "ci_wired": {"type": "boolean"}
      }
    },
    "decision": {"type": "string", "minLength": 20, "pattern": "(\\.(tsx?|jsx?|py|md)\\b|/)"},
    "evidence": {
      "type": "array",
      "minItems": 2,
      "items": {"type": "string", "minLength": 7},
      "allOf": [
        {"contains": {"pattern": "audit"}},
        {"contains": {"pattern": "\\b[0-9a-f]{7,40}\\b"}}
      ]
    },
    "review": {
      "type": "object",
      "required": ["cadence", "next_review_at"],
      "additionalProperties": false,
      "properties": {
        "cadence": {"type": "string", "enum": ["monthly", "quarterly"]},
        "next_review_at": {"$ref": "#/definitions/date"}
      }
    }
  }
}

output-contract.example:
{
  "repo": {"url": "https://github.com/acme/storefront", "commit_sha": "a1b2c3d4e5f", "source_root": "src"},
  "owner": "swe:alice",
  "inputs": [
    {"name": "line_limit", "value": 250},
    {"name": "namespace_import_allowlist", "value": ["react", "three"]}
  ],
  "audit": {
    "command": "bash scripts/llm-arch-audit.sh src 250",
    "file_size": {
      "histogram": [
        {"bucket": "0-100", "files": 212},
        {"bucket": "101-250", "files": 61},
        {"bucket": "251-500", "files": 4},
        {"bucket": "501+", "files": 1}
      ],
      "oversized": [
        {"path": "src/features/checkout/CheckoutPage.tsx", "lines": 1412, "proposed_split": "menu and copy arrays to src/data/checkout.ts; useCheckoutTotals to src/hooks/use-checkout-totals.ts; AddressForm to src/features/checkout/AddressForm.tsx"},
        {"path": "src/components/ProductCard.tsx", "lines": 388, "proposed_split": "price formatting to src/utils/format-price.ts; badges to src/components/ProductBadges.tsx"},
        {"path": "src/utils/helpers.ts", "lines": 302, "proposed_split": "one function per file under src/utils/: format-date.ts, slugify.ts, debounce.ts"}
      ]
    },
    "directory_depth": {
      "limit": 3,
      "feature_limit": 2,
      "violations": [{"path": "src/features/billing/invoices/pdf/renderers/table.ts", "depth": 5}]
    },
    "barrels": ["src/components/index.ts"],
    "wildcard_imports": {
      "lint": "eslint import/no-namespace",
      "hits": [{"path": "src/features/search/SearchPanel.tsx", "line": 3}]
    },
    "naming": {
      "rubric": [
        "file name equals its primary export",
        "components PascalCase, hooks use-*.ts, utils kebab-case",
        "no catch-all names: utils2, misc, helpers, common, stuff",
        "no unexplained abbreviations"
      ],
      "score": 84,
      "offenders": [
        {"path": "src/utils/helpers.ts", "reason": "catch-all name", "proposed_name": "src/utils/format-date.ts"},
        {"path": "src/components/misc/Btn.tsx", "reason": "catch-all directory and abbreviation", "proposed_name": "src/components/Button.tsx"}
      ]
    },
    "inline_data": [{"path": "src/features/checkout/CheckoutPage.tsx", "lines": 214}],
    "claude_md": {"present": true, "line_limit": 250},
    "ci_wired": false
  },
  "decision": "Delete src/components/index.ts and rewrite its 14 importers; split CheckoutPage.tsx into src/data/checkout.ts, use-checkout-totals.ts and AddressForm.tsx; split ProductCard.tsx and helpers.ts as proposed; flatten billing/invoices/pdf/renderers into src/features/billing-invoice-pdf/; replace the namespace import in SearchPanel.tsx; rename misc/Btn.tsx to Button.tsx; then wire the audit into CI.",
  "evidence": [
    "bash scripts/llm-arch-audit.sh src 250",
    "a1b2c3d4e5f",
    "https://github.com/acme/storefront/pull/2210"
  ],
  "review": {"cadence": "quarterly", "next_review_at": "2026-12-12"}
}

{
  "repo": {"url": "https://github.com/acme/storefront", "commit_sha": "a1b2c3d4e5f", "source_root": "src"},
  "owner": "swe:alice",
  "inputs": [
    {"name": "line_limit", "value": 400}
  ],
